def normalize_label_value(value):
    if pd.isna(value):
        return np.nan
    text = str(value).strip().lower()
    text = text.replace("_", "-")
    if text in {"0", "0.0", "non-seizure", "non seizure", "nonseizure", "normal", "ns"}:
        return 0
    if text in {"1", "1.0", "seizure", "ictal", "sz"}:
        return 1
    if "non" in text and "seizure" in text:
        return 0
    if "seizure" in text:
        return 1
    return np.nan


def ensure_standard_columns(df, image_column=None, label_column=None, name="dataset"):
    df = df.copy()

    if "_image_path" not in df.columns:
        if image_column is None:
            raise ValueError(f"{name}: _image_path is missing and image_column was not provided.")
        df["_image_path"] = df[image_column].astype(str)

    if "_label" not in df.columns:
        if label_column is None:
            raise ValueError(f"{name}: _label is missing and label_column was not provided.")
        df["_label"] = df[label_column].apply(normalize_label_value)

    bad_labels = int(df["_label"].isna().sum())
    if bad_labels:
        raise ValueError(f"{name}: {bad_labels} labels could not be normalized.")

    df["_label"] = df["_label"].astype(int)
    df["_class_name"] = np.where(df["_label"].eq(1), "seizure", "non-seizure")

    missing_images = [p for p in df["_image_path"].astype(str).tolist() if not os.path.exists(p)]
    if missing_images:
        print(f"{name}: missing images:", len(missing_images))
        for p in missing_images[:20]:
            print(p)
        raise FileNotFoundError(f"{name}: one or more standardized image paths do not exist.")

    return df.reset_index(drop=True)


