def cache_paths_for_dataframe(df, dataset_name):
    if not USE_LOCAL_IMAGE_CACHE:
        return df

    import hashlib

    cache_subdir = LOCAL_IMAGE_CACHE_DIR / dataset_name.replace(" ", "_")
    cache_subdir.mkdir(parents=True, exist_ok=True)

    new_paths = []
    for src in tqdm(df["_image_path"].astype(str).tolist(), desc=f"Caching {dataset_name} images"):
        src_path = Path(src)
        key = hashlib.md5(str(src_path).encode("utf-8")).hexdigest()[:12]
        dst_path = cache_subdir / f"{key}_{src_path.name}"
        if not dst_path.exists():
            shutil.copy2(src_path, dst_path)
        new_paths.append(str(dst_path))

    df = df.copy()
    df["_original_image_path"] = df["_image_path"]
    df["_image_path"] = new_paths
    return df


if USE_LOCAL_IMAGE_CACHE:
    banner("COPYING IMAGES TO LOCAL COLAB CACHE")
