def label_to_answer(label):
    return "seizure" if int(label) == 1 else "non-seizure"


def load_rgb_image(path):
    with Image.open(path) as image:
        return image.convert("RGB")


class TopomapDataset(Dataset):
    def __init__(self, df):
        self.df = df.reset_index(drop=True)

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):
        row = self.df.iloc[idx]
        return {
            "image_path": str(row["_image_path"]),
            "label": int(row["_label"]),
            "class_name": str(row["_class_name"]),
            "row_index": int(idx),
        }


def make_user_messages(image):
    return [
        {
            "role": "user",
            "content": [
                {"type": "image", "image": image},
                {"type": "text", "text": CLASSIFICATION_PROMPT},
            ],
        }
    ]


def make_train_inputs(image, answer):
    user_messages = make_user_messages(image)
    full_messages = user_messages + [
        {
            "role": "assistant",
            "content": [{"type": "text", "text": answer}],
        }
    ]

    prompt_inputs = processor.apply_chat_template(
        user_messages,
        add_generation_prompt=True,
        tokenize=True,
        return_dict=True,
        return_tensors="pt",
    )

    full_inputs = processor.apply_chat_template(
        full_messages,
        add_generation_prompt=False,
        tokenize=True,
        return_dict=True,
        return_tensors="pt",
    )

    labels = full_inputs["input_ids"].clone()
    prompt_len = int(prompt_inputs["input_ids"].shape[-1])
    if prompt_len >= labels.shape[-1]:
        prompt_len = max(0, labels.shape[-1] - 3)

    labels[:, :prompt_len] = -100
    pad_token_id = getattr(tokenizer, "pad_token_id", None)
    if pad_token_id is not None:
        labels[labels == pad_token_id] = -100

    full_inputs["labels"] = labels
    return full_inputs


def make_generation_inputs(image):
    return processor.apply_chat_template(
        make_user_messages(image),
        add_generation_prompt=True,
        tokenize=True,
        return_dict=True,
        return_tensors="pt",
    )


def train_collate(batch):
    item = batch[0]
    image = load_rgb_image(item["image_path"])
    answer = label_to_answer(item["label"])
    inputs = make_train_inputs(image, answer)
    return inputs, item


train_loader = DataLoader(
    TopomapDataset(train_df),
    batch_size=PHYSICAL_BATCH_SIZE,
    shuffle=True,
    num_workers=NUM_WORKERS,
    collate_fn=train_collate,
)


