processor = AutoProcessor.from_pretrained(MODEL_ID)
tokenizer = getattr(processor, "tokenizer", processor)

if getattr(tokenizer, "pad_token_id", None) is None and getattr(tokenizer, "eos_token", None) is not None:
    tokenizer.pad_token = tokenizer.eos_token


def load_medgemma_model():
    common_kwargs = {
        "low_cpu_mem_usage": True,
        "attn_implementation": "eager",
    }

    attempts = [
        {"dtype": MODEL_DTYPE, **common_kwargs},
        {"torch_dtype": MODEL_DTYPE, **common_kwargs},
        {"dtype": MODEL_DTYPE, "low_cpu_mem_usage": True},
        {"torch_dtype": MODEL_DTYPE, "low_cpu_mem_usage": True},
    ]

    last_error = None
    for kwargs in attempts:
        try:
            return AutoModelForImageTextToText.from_pretrained(MODEL_ID, **kwargs)
        except TypeError as error:
            last_error = error
            continue

    raise last_error


model = load_medgemma_model()
model.to(DEVICE)
model.eval()

if hasattr(model, "gradient_checkpointing_disable"):
    model.gradient_checkpointing_disable()

if hasattr(model.config, "use_cache"):
    model.config.use_cache = True

for parameter in model.parameters():
    parameter.requires_grad_(False)

print("Model loaded and frozen.")


# ==================================================================================================
# 8. LOREFT INTERVENTIONS
# ==================================================================================================

def get_nested_attr(obj, path):
    current = obj
    for part in path.split("."):
        if not hasattr(current, part):
            return None
        current = getattr(current, part)
    return current


def get_language_layers(model):
    candidate_paths = [
        "language_model.model.layers",
        "language_model.layers",
        "model.language_model.model.layers",
        "model.language_model.layers",
        "model.layers",
    ]

    for path in candidate_paths:
        layers = get_nested_attr(model, path)
        if layers is not None and hasattr(layers, "__len__") and len(layers) > max(LOREFT_LAYERS):
            print("Language layers found at:", path)
            return layers

    raise RuntimeError("Could not find the language-model decoder layers for LoReFT hooks.")


def infer_hidden_size(model, layers):
    config_candidates = [
        getattr(model.config, "text_config", None),
        getattr(model.config, "language_config", None),
        getattr(model, "language_model", None).config if hasattr(model, "language_model") else None,
        model.config,
    ]

    for config in config_candidates:
        if config is not None and hasattr(config, "hidden_size"):
            return int(config.hidden_size)

    first_layer = layers[0]
    for module in first_layer.modules():
        if isinstance(module, nn.Linear):
            return int(module.in_features)

    raise RuntimeError("Could not infer hidden size.")


class LoReFTIntervention(nn.Module):
    def __init__(self, hidden_size, rank, prefix_positions, suffix_positions, dropout):
        super().__init__()
        self.hidden_size = int(hidden_size)
        self.rank = int(rank)
        self.prefix_positions = int(prefix_positions)
        self.suffix_positions = int(suffix_positions)
        self.down = nn.Linear(hidden_size, rank, bias=True)
        self.dropout = nn.Dropout(dropout)
        self.up = nn.Linear(rank, hidden_size, bias=False)

        nn.init.kaiming_uniform_(self.down.weight, a=math.sqrt(5))
        nn.init.zeros_(self.down.bias)
        nn.init.zeros_(self.up.weight)

    def _positions(self, seq_len, device):
        positions = []
        if self.prefix_positions > 0:
            positions.extend(range(0, min(self.prefix_positions, seq_len)))
        if self.suffix_positions > 0:
            start = max(seq_len - self.suffix_positions, 0)
            positions.extend(range(start, seq_len))
        positions = sorted(set(positions))
        return torch.tensor(positions, dtype=torch.long, device=device)

    def forward(self, hidden_states):
        if hidden_states.ndim != 3:
            return hidden_states

        seq_len = hidden_states.shape[1]
        positions = self._positions(seq_len, hidden_states.device)
        if positions.numel() == 0:
            return hidden_states

        selected = hidden_states.index_select(dim=1, index=positions).float()
        with torch.autocast(device_type="cuda", enabled=False):
            delta = self.up(self.dropout(self.down(selected)))
        delta = delta.to(dtype=hidden_states.dtype)

        output = hidden_states.clone()
        output[:, positions, :] = output[:, positions, :] + delta
        return output


language_layers = get_language_layers(model)
hidden_size = infer_hidden_size(model, language_layers)
print("Hidden size:", hidden_size)
print("LoReFT layers:", LOREFT_LAYERS)

loreft_interventions = nn.ModuleDict(
    {
        f"layer_{layer_idx}": LoReFTIntervention(
            hidden_size=hidden_size,
            rank=LOREFT_RANK,
            prefix_positions=LOREFT_PREFIX_POSITIONS,
            suffix_positions=LOREFT_SUFFIX_POSITIONS,
            dropout=LOREFT_DROPOUT,
        )
        for layer_idx in LOREFT_LAYERS
    }
)
loreft_interventions.to(DEVICE)
loreft_interventions.float()

hook_handles = []


def make_loreft_hook(layer_idx):
    key = f"layer_{layer_idx}"

    def hook(module, inputs, output):
        if isinstance(output, tuple):
            hidden_states = output[0]
            new_hidden_states = loreft_interventions[key](hidden_states)
            return (new_hidden_states,) + output[1:]

        return loreft_interventions[key](output)

    return hook


for layer_idx in LOREFT_LAYERS:
    handle = language_layers[layer_idx].register_forward_hook(make_loreft_hook(layer_idx))
    hook_handles.append(handle)

trainable_params = sum(p.numel() for p in loreft_interventions.parameters() if p.requires_grad)
print("Trainable LoReFT parameters:", f"{trainable_params:,}")
print("Expected with hidden_size=2560:", "81,936")


# ==================================================================================================
# 9. FORWARD, GENERATION, METRICS
# ==================================================================================================

def move_inputs_to_device(inputs):
    moved = {}
    for key, value in inputs.items():
        if torch.is_tensor(value):
            if value.is_floating_point():
                moved[key] = value.to(device=DEVICE, dtype=MODEL_DTYPE)
            else:
                moved[key] = value.to(device=DEVICE)
        else:
            moved[key] = value
    return moved


def model_forward(inputs):
    try:
        return model(**inputs)
    except TypeError as error:
        allowed = set(inspect.signature(model.forward).parameters.keys())
        filtered = {k: v for k, v in inputs.items() if k in allowed}
        if len(filtered) == len(inputs):
            raise error
        return model(**filtered)


def model_generate(inputs):
    generation_kwargs = {
        "max_new_tokens": MAX_NEW_TOKENS,
        "do_sample": False,
        "use_cache": True,
    }

    eos_token_id = getattr(tokenizer, "eos_token_id", None)
    pad_token_id = getattr(tokenizer, "pad_token_id", None)
    if eos_token_id is not None:
        generation_kwargs["eos_token_id"] = eos_token_id
    if pad_token_id is not None:
        generation_kwargs["pad_token_id"] = pad_token_id

    try:
        return model.generate(**inputs, **generation_kwargs)
    except TypeError as error:
        allowed = set(inspect.signature(model.forward).parameters.keys())
        filtered = {k: v for k, v in inputs.items() if k in allowed}
        if len(filtered) == len(inputs):
            raise error
        return model.generate(**filtered, **generation_kwargs)


def normalize_prediction_text(text):
    if text is None:
        return np.nan

    raw = str(text).strip().lower()
    if not raw:
        return np.nan

    first_line = raw.splitlines()[0].strip()
    candidates = [first_line, raw]

    for candidate in candidates:
        candidate = candidate.replace("_", "-")
        cleaned = re.sub(r"[^a-z\- ]+", " ", candidate)
        cleaned = re.sub(r"\s+", " ", cleaned).strip()

        if cleaned in {"non-seizure", "non seizure", "nonseizure", "normal", "ns"}:
            return 0
        if cleaned in {"seizure", "ictal", "sz"}:
            return 1
        if "non-seizure" in cleaned or "non seizure" in cleaned or "nonseizure" in cleaned:
            return 0
        if "not seizure" in cleaned:
            return 0
        if "seizure" in cleaned:
            return 1

    return np.nan


def compute_metrics(y_true, y_pred_raw):
    y_true = np.asarray(y_true, dtype=int)
    y_pred_raw = np.asarray(y_pred_raw, dtype=float)

    invalid_mask = np.isnan(y_pred_raw)
    y_pred_metric = y_pred_raw.copy()
    y_pred_metric[invalid_mask] = 1 - y_true[invalid_mask]
    y_pred_metric = y_pred_metric.astype(int)

    cm = confusion_matrix(y_true, y_pred_metric, labels=[0, 1])
    tn, fp, fn, tp = cm.ravel()

    metrics = {
        "accuracy": float(accuracy_score(y_true, y_pred_metric)),
        "balanced_accuracy": float(balanced_accuracy_score(y_true, y_pred_metric)),
        "sensitivity_recall_seizure": float(recall_score(y_true, y_pred_metric, pos_label=1, zero_division=0)),
        "specificity_recall_non_seizure": float(recall_score(y_true, y_pred_metric, pos_label=0, zero_division=0)),
        "precision_seizure": float(precision_score(y_true, y_pred_metric, pos_label=1, zero_division=0)),
        "f1_seizure": float(f1_score(y_true, y_pred_metric, pos_label=1, zero_division=0)),
        "invalid_prediction_count": int(invalid_mask.sum()),
        "tn": int(tn),
        "fp": int(fp),
        "fn": int(fn),
        "tp": int(tp),
    }

    cm_df = pd.DataFrame(
        cm,
        index=["Actual Non-seizure", "Actual Seizure"],
        columns=["Predicted Non-seizure", "Predicted Seizure"],
    )
    return metrics, cm_df, y_pred_metric


def print_metric_block(name, metrics):
    print(f"\n{name}")
    print("-" * len(name))
    print(f"Accuracy             : {metrics['accuracy'] * 100:.2f}%")
    print(f"Balanced accuracy    : {metrics['balanced_accuracy'] * 100:.2f}%")
    print(f"Sensitivity seizure  : {metrics['sensitivity_recall_seizure'] * 100:.2f}%")
    print(f"Specificity non-seiz.: {metrics['specificity_recall_non_seizure'] * 100:.2f}%")
    print(f"Precision seizure    : {metrics['precision_seizure'] * 100:.2f}%")
    print(f"F1 seizure           : {metrics['f1_seizure']:.4f}")
    print(f"Invalid predictions  : {metrics['invalid_prediction_count']}")


@torch.no_grad()
def calculate_validation_loss(df):
    model.eval()
    loreft_interventions.eval()

    losses = []
    for _, row in tqdm(df.iterrows(), total=len(df), desc="Validation loss"):
        image = load_rgb_image(row["_image_path"])
        answer = label_to_answer(row["_label"])
        inputs = make_train_inputs(image, answer)
        inputs = move_inputs_to_device(inputs)

        with torch.autocast(device_type="cuda", dtype=MODEL_DTYPE, enabled=DEVICE.type == "cuda"):
            outputs = model_forward(inputs)
            loss = outputs.loss

        losses.append(float(loss.detach().cpu()))

    return float(np.mean(losses))


@torch.no_grad()
def evaluate_generation_on_df(df, dataset_name):
    model.eval()
    loreft_interventions.eval()

    records = []
    y_true = []
    y_pred_raw = []

    iterator = tqdm(df.iterrows(), total=len(df), desc=f"Generating {dataset_name}")
    for row_number, row in iterator:
        image = load_rgb_image(row["_image_path"])
        inputs = make_generation_inputs(image)
        inputs = move_inputs_to_device(inputs)
        prompt_len = int(inputs["input_ids"].shape[-1])

        with torch.autocast(device_type="cuda", dtype=MODEL_DTYPE, enabled=DEVICE.type == "cuda"):
            generated_ids = model_generate(inputs)

        new_tokens = generated_ids[:, prompt_len:]
        prediction_text = tokenizer.batch_decode(new_tokens, skip_special_tokens=True)[0].strip()
        pred_label = normalize_prediction_text(prediction_text)

        true_label = int(row["_label"])
        y_true.append(true_label)
        y_pred_raw.append(pred_label)

        record = row.to_dict()
        record["prediction_text"] = prediction_text
        record["normalized_prediction"] = pred_label
        record["true_label"] = true_label
        record["true_class"] = label_to_answer(true_label)
        records.append(record)

    metrics, cm_df, y_pred_metric = compute_metrics(y_true, y_pred_raw)
    pred_df = pd.DataFrame(records)
    pred_df["metric_prediction"] = y_pred_metric
    pred_df["metric_prediction_class"] = [label_to_answer(x) for x in y_pred_metric]
    return pred_df, metrics, cm_df


# ==================================================================================================
# 10. CHECKPOINT HELPERS
# ==================================================================================================

def save_json(obj, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2)


def save_loreft_weights(directory, epoch, metrics):
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    torch.save(loreft_interventions.state_dict(), directory / "loreft_intervention.pt")

    config = {
        "model_id": MODEL_ID,
        "representation": "A5D5D4D3D2",
        "epoch": int(epoch),
        "loreft_rank": LOREFT_RANK,
        "loreft_layers": LOREFT_LAYERS,
        "prefix_positions": LOREFT_PREFIX_POSITIONS,
        "suffix_positions": LOREFT_SUFFIX_POSITIONS,
        "dropout": LOREFT_DROPOUT,
        "learning_rate": LEARNING_RATE,
        "weight_decay": WEIGHT_DECAY,
        "grad_accum_steps": GRAD_ACCUM_STEPS,
        "prompt": CLASSIFICATION_PROMPT,
        "metrics": metrics,
    }
    save_json(config, directory / "loreft_config.json")


def save_training_state(epoch, global_step, best_val_ba, best_val_loss, bad_epochs, optimizer, scheduler):
    LATEST_CHECKPOINT_DIR.mkdir(parents=True, exist_ok=True)
    torch.save(
        {
            "epoch": int(epoch),
            "global_step": int(global_step),
            "best_val_ba": float(best_val_ba),
            "best_val_loss": float(best_val_loss),
            "bad_epochs": int(bad_epochs),
            "loreft_state_dict": loreft_interventions.state_dict(),
            "optimizer_state_dict": optimizer.state_dict(),
            "scheduler_state_dict": scheduler.state_dict(),
        },
        LATEST_CHECKPOINT_DIR / "training_state.pt",
    )


def load_loreft_weights(weights_path):
    try:
        state_dict = torch.load(weights_path, map_location=DEVICE, weights_only=True)
    except TypeError:
        state_dict = torch.load(weights_path, map_location=DEVICE)
    loreft_interventions.load_state_dict(state_dict)
    loreft_interventions.to(DEVICE)
    loreft_interventions.float()


# ==================================================================================================
# 11. TRAIN LOREFT
# ==================================================================================================

optimizer = torch.optim.AdamW(
    loreft_interventions.parameters(),
    lr=LEARNING_RATE,
    weight_decay=WEIGHT_DECAY,
)

steps_per_epoch = math.ceil(len(train_loader) / GRAD_ACCUM_STEPS)
total_training_steps = steps_per_epoch * MAX_EPOCHS
warmup_steps = int(total_training_steps * WARMUP_RATIO)

scheduler = get_linear_schedule_with_warmup(
    optimizer,
    num_warmup_steps=warmup_steps,
    num_training_steps=total_training_steps,
)

start_epoch = 1
global_step = 0
best_val_ba = -1.0
best_val_loss = float("inf")
bad_epochs = 0

if RESUME_TRAINING:
    if RESUME_TRAINING_STATE is None:
        RESUME_TRAINING_STATE = LATEST_CHECKPOINT_DIR / "training_state.pt"
    RESUME_TRAINING_STATE = Path(RESUME_TRAINING_STATE)
    if not RESUME_TRAINING_STATE.exists():
        raise FileNotFoundError(f"Resume state not found: {RESUME_TRAINING_STATE}")

    try:
        state = torch.load(RESUME_TRAINING_STATE, map_location=DEVICE, weights_only=False)
    except TypeError:
        state = torch.load(RESUME_TRAINING_STATE, map_location=DEVICE)

    loreft_interventions.load_state_dict(state["loreft_state_dict"])
    optimizer.load_state_dict(state["optimizer_state_dict"])
    scheduler.load_state_dict(state["scheduler_state_dict"])
    start_epoch = int(state["epoch"]) + 1
    global_step = int(state["global_step"])
    best_val_ba = float(state["best_val_ba"])
    best_val_loss = float(state["best_val_loss"])
    bad_epochs = int(state["bad_epochs"])
    print("Resumed from:", RESUME_TRAINING_STATE)
    print("Starting epoch:", start_epoch)

training_history = []

banner("TRAINING LOREFT")
print("Epochs:", MAX_EPOCHS)
print("Steps/epoch:", steps_per_epoch)
print("Warmup steps:", warmup_steps)
print("Early stopping patience:", EARLY_STOPPING_PATIENCE)

for epoch in range(start_epoch, MAX_EPOCHS + 1):
    model.eval()
    loreft_interventions.train()

    optimizer.zero_grad(set_to_none=True)
    running_loss = 0.0
    completed_optimizer_steps = 0

    progress = tqdm(train_loader, desc=f"Epoch {epoch:03d}/{MAX_EPOCHS}")
    for batch_idx, (inputs, item) in enumerate(progress):
        inputs = move_inputs_to_device(inputs)

        with torch.autocast(device_type="cuda", dtype=MODEL_DTYPE, enabled=DEVICE.type == "cuda"):
            outputs = model_forward(inputs)
            loss = outputs.loss
            loss_for_backward = loss / GRAD_ACCUM_STEPS

        loss_for_backward.backward()
        running_loss += float(loss.detach().cpu())

        should_step = ((batch_idx + 1) % GRAD_ACCUM_STEPS == 0) or ((batch_idx + 1) == len(train_loader))
        if should_step:
            torch.nn.utils.clip_grad_norm_(loreft_interventions.parameters(), MAX_GRAD_NORM)
            optimizer.step()
            scheduler.step()
            optimizer.zero_grad(set_to_none=True)
            global_step += 1
            completed_optimizer_steps += 1

        progress.set_postfix(
            {
                "loss": f"{running_loss / (batch_idx + 1):.4f}",
                "lr": f"{scheduler.get_last_lr()[0]:.2e}",
            }
        )

    train_loss = running_loss / max(1, len(train_loader))

    val_loss = calculate_validation_loss(val_df)
    val_pred_df, val_metrics, val_cm_df = evaluate_generation_on_df(val_df, f"validation epoch {epoch:03d}")
    val_ba = val_metrics["balanced_accuracy"]

    epoch_metrics = {
        "epoch": int(epoch),
        "global_step": int(global_step),
        "train_loss": float(train_loss),
        "val_loss": float(val_loss),
        **{f"val_{k}": v for k, v in val_metrics.items()},
    }
    training_history.append(epoch_metrics)

    epoch_dir = CHECKPOINT_DIR / f"e{epoch:03d}"
    save_loreft_weights(epoch_dir, epoch, epoch_metrics)
    val_pred_df.to_csv(epoch_dir / "validation_predictions.csv", index=False)
    val_cm_df.to_csv(epoch_dir / "validation_confusion_matrix.csv")
    save_json(epoch_metrics, epoch_dir / "validation_metrics.json")

    improved = (val_ba > best_val_ba + 1e-12) or (
        abs(val_ba - best_val_ba) <= 1e-12 and val_loss < best_val_loss
    )

    if improved:
        best_val_ba = val_ba
        best_val_loss = val_loss
        bad_epochs = 0
        save_loreft_weights(BEST_CHECKPOINT_DIR, epoch, epoch_metrics)
        val_pred_df.to_csv(BEST_CHECKPOINT_DIR / "best_validation_predictions.csv", index=False)
        val_cm_df.to_csv(BEST_CHECKPOINT_DIR / "best_validation_confusion_matrix.csv")
        print(f"\nNew best epoch: {epoch} | val BA={best_val_ba * 100:.2f}% | val loss={best_val_loss:.4f}")
    else:
        bad_epochs += 1
        print(f"\nNo improvement. Bad epochs: {bad_epochs}/{EARLY_STOPPING_PATIENCE}")

    pd.DataFrame(training_history).to_csv(OUTPUT_ROOT / "training_history.csv", index=False)
    save_training_state(epoch, global_step, best_val_ba, best_val_loss, bad_epochs, optimizer, scheduler)

    print_metric_block(f"Validation epoch {epoch:03d}", val_metrics)
    print(val_cm_df)

    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()

    if bad_epochs >= EARLY_STOPPING_PATIENCE:
        print(f"\nEarly stopping triggered at epoch {epoch}.")
        break


# ==================================================================================================
# 12. LOAD BEST LOREFT AND EVALUATE EACH BLINDED PATIENT
# ==================================================================================================

banner("LOADING BEST LOREFT CHECKPOINT")
best_weights = BEST_CHECKPOINT_DIR / "loreft_intervention.pt"
if not best_weights.exists():
    raise FileNotFoundError(f"Best LoReFT weights not found: {best_weights}")

load_loreft_weights(best_weights)
model.eval()
loreft_interventions.eval()
print("Loaded:", best_weights)

banner("PATIENTWISE BLINDED TEST EVALUATION")

all_patient_metrics = []

for patient_id, test_df in testing_dfs.items():
    patient_name = f"Patient {patient_id}"
    patient_dir = OUTPUT_ROOT / f"Patient_{patient_id}"
    patient_dir.mkdir(parents=True, exist_ok=True)

    pred_df, metrics, cm_df = evaluate_generation_on_df(test_df, patient_name)

    pred_path = patient_dir / "test_predictions.csv"
    metrics_path = patient_dir / "test_metrics.json"
    cm_path = patient_dir / "confusion_matrix.csv"

    pred_df.to_csv(pred_path, index=False)
    save_json(metrics, metrics_path)
    cm_df.to_csv(cm_path)

    row = {"patient": patient_id, **metrics}
    all_patient_metrics.append(row)

    print_metric_block(patient_name, metrics)
    print(cm_df)
    try:
        display(cm_df)
    except Exception:
        pass

summary_df = pd.DataFrame(all_patient_metrics)
summary_path = OUTPUT_ROOT / "patientwise_test_summary.csv"
summary_df.to_csv(summary_path, index=False)

banner("DONE")
print("Saved run folder:", OUTPUT_ROOT)
print("Patientwise summary:", summary_path)
display(summary_df)

