USER_PROMPT = """
You are an expert in classifying seizure and non-seizure EEG patterns from composite wavelet-coefficient variance topomaps.
The attached composite image represents one 2-second EEG window.
In each composite image, the panels from left to right are: A5 approximation-coefficient variance (approximately 0-4 Hz), D5 detail-coefficient variance (approximately 4-8 Hz), D4 detail-coefficient variance (approximately 8-16 Hz), D3 detail-coefficient variance (approximately 16-32 Hz), and D2 detail-coefficient variance (approximately 32-64 Hz).
The EEG was divided into non-overlapping 2-second windows, filtered using a fourth-order Butterworth 59-61 Hz band-stop filter, and decomposed using a level-5 Discrete Wavelet Transform. For each bipolar EEG channel, the A5, D5, D4, D3, and D2 coefficient variances were calculated and spatially interpolated at the midpoint between the two electrodes to create the topomaps.
Each panel uses its own fixed coefficient-specific color scale across the complete dataset. Therefore, evaluate the relative intensity and spatial distribution within each panel independently. Do not assume that the same color represents the same numerical variance across different panels. Yellow indicates relatively higher coefficient variance within the corresponding panel, while dark purple indicates relatively lower coefficient variance.
Internally evaluate the image in six steps:
- Examine the A5 panel for the intensity, spatial extent, localization, symmetry, and organization of elevated variance.
- Examine the D5 panel independently using the same characteristics.
- Examine the D4 panel independently using the same characteristics.
- Examine the D3 panel independently using the same characteristics.
- Examine the D2 panel independently using the same characteristics.
- Combine the evidence from all five panels and determine whether the overall composite pattern is more consistent with seizure or non-seizure activity.
Seizure-related evidence may appear across all five panels or may be more prominent in only a subset of panels. Do not require all panels to show equally strong elevated variance before predicting seizure.
Consider whether elevated variance is focal or widespread, symmetric or asymmetric, and spatially organized or irregular. Evaluate all five panels together rather than relying on brightness, one isolated region, or any single panel as a definitive feature.
Return exactly one label:
Seizure
Non-Seizure
""".strip()

