def choose_existing_or_parent_path(paths):
    paths = [os.path.normpath(str(path)) for path in paths]

    for path in paths:
        if os.path.exists(path):
            return path

    for path in paths:
        parent = os.path.dirname(path)
        if os.path.isdir(parent):
            return path

    return paths[0]


def drive_path(*parts):
    return os.path.join(*parts)


def extract_google_drive_file_id(url):
    url = str(url).strip()

    patterns = [
        r"/file/d/([^/]+)",
        r"[?&]id=([^&]+)",
        r"/d/([^/]+)",
    ]
    for pattern in patterns:
        match = re.search(pattern, url)
        if match is not None:
            return match.group(1).strip()

    if re.fullmatch(r"[A-Za-z0-9_-]{20,}", url):
        return url

    raise ValueError(f"Could not extract Google Drive file id from: {url}")


def ensure_gdown_available():
    try:
        import gdown  # noqa: F401
    except Exception:
        print("\nInstalling gdown for Google Drive CSV downloads...")
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "gdown"])


def download_drive_file_with_authenticated_api(file_id, output_path):
    print("\nTrying authenticated Google Drive API fallback...")
    print("This works for private files if your Colab account has access.")

    try:
        from google.colab import auth
        auth.authenticate_user()
    except Exception as error:
        raise RuntimeError(
            "\nCould not authenticate this Colab session for Google Drive API access."
        ) from error

    try:
        from google.auth import default
        from googleapiclient.discovery import build
        from googleapiclient.http import MediaIoBaseDownload
    except Exception:
        print("\nInstalling Google API client packages...")
        subprocess.check_call([
            sys.executable,
            "-m",
            "pip",
            "install",
            "-q",
            "google-api-python-client",
            "google-auth",
            "google-auth-httplib2",
        ])
        from google.auth import default
        from googleapiclient.discovery import build
        from googleapiclient.http import MediaIoBaseDownload

    credentials, _ = default()
    service = build("drive", "v3", credentials=credentials)

    try:
        metadata = service.files().get(
            fileId=file_id,
            fields="id,name,mimeType,size",
            supportsAllDrives=True,
        ).execute()
        print("Drive file:", metadata.get("name"), "| MIME:", metadata.get("mimeType"))

        request = service.files().get_media(
            fileId=file_id,
            supportsAllDrives=True,
        )

        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        with open(output_path, "wb") as file_handle:
            downloader = MediaIoBaseDownload(file_handle, request)
            done = False
            while not done:
                status, done = downloader.next_chunk()
                if status is not None:
                    print(f"Download progress: {100.0 * status.progress():.1f}%")

    except Exception as error:
        raise RuntimeError(
            "\nAuthenticated Google Drive API download failed.\n"
            "Make sure the same Google account used in Colab can open this file link.\n"
            f"File id: {file_id}"
        ) from error

    if not os.path.isfile(output_path) or os.path.getsize(output_path) == 0:
        raise RuntimeError(f"Google Drive API created an empty/missing file: {output_path}")

    return output_path


def download_drive_csv(url, output_path):
    ensure_gdown_available()
    import gdown

    file_id = extract_google_drive_file_id(url)
    download_url = f"https://drive.google.com/uc?id={file_id}"

    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    print("\nDownloading CSV from Google Drive")
    print("File id:", file_id)
    print("Saving :", output_path)

    result = None
    try:
        result = gdown.download(
            download_url,
            output_path,
            quiet=False,
            fuzzy=True,
        )
    except Exception as error:
        print("\ngdown could not download this file.")
        print("gdown error:", repr(error))

    if result is None or not os.path.isfile(output_path):
        download_drive_file_with_authenticated_api(file_id, output_path)

    try:
        preview = pd.read_csv(output_path, nrows=3)
    except Exception as error:
        raise RuntimeError(
            "\nThe downloaded file is not readable as a CSV. "
            "Check that the link points directly to a CSV file.\n"
            f"Downloaded path: {output_path}"
        ) from error

    print(f"CSV OK: {output_path} | preview shape: {preview.shape}")
    return output_path


def download_csv_links_if_enabled():
    if not USE_CSV_LINKS:
        return None

    required_keys = ["train", "08", "11", "18", "24"]
    missing = [key for key in required_keys if key not in CSV_LINKS or not CSV_LINKS[key]]
    if missing:
        raise ValueError(f"Missing CSV links for: {missing}")

    downloaded = {}
    for key in required_keys:
        output_name = {
            "train": "training_A5D5D4D3D2.csv",
            "08": "patient_08_A5D5D4D3D2_test.csv",
            "11": "patient_11_A5D5D4D3D2_test.csv",
            "18": "patient_18_A5D5D4D3D2_test.csv",
            "24": "patient_24_A5D5D4D3D2_test.csv",
        }[key]
        downloaded[key] = download_drive_csv(
            CSV_LINKS[key],
            os.path.join(CSV_DOWNLOAD_DIR, output_name),
        )

    return downloaded


