def clean_path(value):
    if pd.isna(value):
        return ""
    value = str(value).strip().strip('"').strip("'")
    value = os.path.expandvars(value)
    value = os.path.expanduser(value)
    return os.path.normpath(value)


def path_spelling_variants(path):
    path = clean_path(path)
    candidates = [path]
    replacements = [
        ("Patiient 24", "Patient 24"),
        ("Patient 24", "Patiient 24"),
        ("All training together RAw", "All training together RAW"),
        ("All training together RAW", "All training together RAw"),
        ("bLINDED", "Blinded"),
        ("Blinded", "bLINDED"),
        ("Blinnded", "Blinded"),
        ("Blinded", "Blinnded"),
        ("Blinded folder", "Blinded"),
        ("Blinded", "Blinded folder"),
        ("Blinded Topomaps", "Blinded"),
        ("Blinded", "Blinded Topomaps"),
        ("TRAINING_TESTING_SPLIT", "TRAINING_TESTING_SPLIT_seed_99"),
        ("TRAINING_TESTING_SPLIT_seed_99", "TRAINING_TESTING_SPLIT"),
    ]

    # Apply replacements iteratively so combined fixes also appear, e.g.
    # Patiient 24 + Blinded -> Patient 24 + Blinded Topomaps.
    for _ in range(4):
        current_candidates = list(candidates)
        for candidate in current_candidates:
            for old, new in replacements:
                if old in candidate:
                    candidates.append(candidate.replace(old, new))

    return unique_keep_order(candidates)


def csv_path_spelling_variants(csv_path):
    return path_spelling_variants(csv_path)


def patient_id_from_dataset_name(dataset_name):
    match = re.search(r"patient[\s_\-]*(\d+)", str(dataset_name), flags=re.IGNORECASE)
    if match is None:
        return None
    return match.group(1).lstrip("0") or "0"


def score_csv_candidate(csv_path, patient_id):
    basename = os.path.basename(csv_path).lower()
    score = 0

    if "blind" in basename:
        score += 20
    text = str(csv_path).replace("\\", "/").lower()

    if "a4d4d3d2" in text:
        score += 30
    if "raw" in basename or "a1" in basename or "a4d4d3d2" in basename:
        score += 10
    if "label" in basename:
        score += 5

    if patient_id is not None:
        patient_tokens = {
            patient_id,
            patient_id.zfill(2),
            f"patient_{patient_id}",
            f"patient_{patient_id.zfill(2)}",
            f"patient{patient_id}",
            f"patient{patient_id.zfill(2)}",
        }
        if any(token.lower() in basename for token in patient_tokens):
            score += 50

    return score

def available_drive_search_roots():
    roots = []

    for root in globals().get("DRIVE_ROOT_CANDIDATES", []):
        if os.path.isdir(root):
            roots.append(root)

    mydrive = globals().get("DRIVE_MYDRIVE", "/content/drive/MyDrive")
    if not roots and os.path.isdir(mydrive):
        roots.append(mydrive)

    return unique_keep_order(roots)


def search_google_drive_for_csv(csv_path, dataset_name):
    representation = globals().get("REPRESENTATION_NAME", "A5D5D4D3D2").lower()
    patient_id = patient_id_from_dataset_name(dataset_name)
    expected_basename = os.path.basename(clean_path(csv_path)).lower()

    matches = []
    roots = available_drive_search_roots()

    if not roots:
        return matches

    patient_tokens = []
    if patient_id is not None:
        patient_tokens = [
            patient_id,
            patient_id.zfill(2),
            f"patient {patient_id}",
            f"patient {patient_id.zfill(2)}",
            f"patient_{patient_id}",
            f"patient_{patient_id.zfill(2)}",
            f"patient{patient_id}",
            f"patient{patient_id.zfill(2)}",
        ]

    for root in roots:
        for dirpath, _, filenames in os.walk(root):
            dir_text = dirpath.replace("\\", "/").lower()

            if representation not in dir_text:
                continue

            if patient_tokens and not any(token in dir_text for token in patient_tokens):
                continue

            if patient_id is None and "training" not in dir_text:
                continue

            for filename in filenames:
                if not filename.lower().endswith(".csv"):
                    continue

                candidate = os.path.join(dirpath, filename)
                candidate_text = candidate.replace("\\", "/").lower()

                if representation not in candidate_text:
                    continue

                if patient_tokens and not any(token in candidate_text for token in patient_tokens):
                    continue

                if patient_id is None:
                    if "training" not in candidate_text:
                        continue
                else:
                    if "blind" not in candidate_text and "test" not in candidate_text:
                        continue

                score = score_csv_candidate(candidate, patient_id)
                if filename.lower() == expected_basename:
                    score += 100
                if representation in filename.lower():
                    score += 30
                if "label" in filename.lower():
                    score += 10
                if "metadata" in filename.lower():
                    score += 5
                if "blind" in candidate_text:
                    score += 10
                if "test" in candidate_text:
                    score += 5
                if "training" in candidate_text and patient_id is None:
                    score += 20

                matches.append((score, candidate))

    matches = sorted(matches, reverse=True)
    return unique_keep_order([candidate for _, candidate in matches])


def google_drive_path_variants(path):
    path = clean_path(path)
    if not path:
        return []

    normalized = path.replace("\\", "/")
    variants = []

    markers = [
        "Fine Tuning for upload/",
        "Fine Tuning/",
    ]

    for marker in markers:
        if marker in normalized:
            suffix = normalized.split(marker, 1)[1]
            for suffix_variant in path_spelling_variants(suffix):
                suffix_variant = suffix_variant.replace("\\", "/")
                for root in globals().get("DRIVE_ROOT_CANDIDATES", []):
                    variants.append(os.path.join(root, *suffix_variant.split("/")))

    return unique_keep_order(variants)



def resolve_csv_path(csv_path, dataset_name):
    csv_path = clean_path(csv_path)

    for candidate in csv_path_spelling_variants(csv_path):
        if os.path.isfile(candidate):
            if candidate != csv_path:
                print("\nCSV path repaired:")
                print("Original:", csv_path)
                print("Using   :", candidate)
            return candidate

    patient_id = patient_id_from_dataset_name(dataset_name)

    possible_parent_dirs = []
    for candidate in csv_path_spelling_variants(csv_path):
        possible_parent_dirs.append(os.path.dirname(candidate))

    possible_csvs = []
    for parent_dir in unique_keep_order(possible_parent_dirs):
        if not os.path.isdir(parent_dir):
            continue

        for filename in os.listdir(parent_dir):
            if filename.lower().endswith(".csv"):
                possible_csvs.append(os.path.join(parent_dir, filename))

    possible_csvs = unique_keep_order(possible_csvs)

    if not possible_csvs:
        drive_csvs = search_google_drive_for_csv(csv_path, dataset_name)
        if len(drive_csvs) == 1:
            print("\nCSV found by searching Google Drive:")
            print("Original:", csv_path)
            print("Using   :", drive_csvs[0])
            return drive_csvs[0]
        if len(drive_csvs) > 1:
            print("\nCSV found by searching Google Drive:")
            print("Original:", csv_path)
            print("Using   :", drive_csvs[0])
            print("Other candidates:")
            for candidate in drive_csvs[1:10]:
                print(candidate)
            return drive_csvs[0]

    if len(possible_csvs) == 1:
        print("\nCSV filename repaired from the containing folder:")
        print("Original:", csv_path)
        print("Using   :", possible_csvs[0])
        return possible_csvs[0]

    if len(possible_csvs) > 1:
        scored = sorted(
            [
                (score_csv_candidate(candidate, patient_id), candidate)
                for candidate in possible_csvs
            ],
            reverse=True,
        )

        best_score, best_candidate = scored[0]
        tied_best = [
            candidate
            for score, candidate in scored
            if score == best_score
        ]

        if best_score > 0 and len(tied_best) == 1:
            print("\nCSV filename repaired from the containing folder:")
            print("Original:", csv_path)
            print("Using   :", best_candidate)
            return best_candidate

        print("\nCSV does not exist, and multiple CSV files were found in the folder.")
        print("Please choose the correct one from these candidates:")
        for _, candidate in scored:
            print(candidate)

    raise FileNotFoundError(f"\nCSV does not exist:\n{csv_path}")


def unique_keep_order(values):
    seen = set()
    ordered = []

    for value in values:
        if value is None:
            continue

        value = str(value).strip()
        if not value:
            continue

        if value not in seen:
            seen.add(value)
            ordered.append(value)

    return ordered


def filename_candidates_from_row(row, image_column):
    candidates = []

    for column in row.index:
        lower = str(column).lower()
        if "filename" in lower or lower in {"file", "image_name", "image"}:
            value = clean_path(row[column])
            if value:
                candidates.append(os.path.basename(value))

    original_path = clean_path(row[image_column])
    if original_path:
        candidates.append(os.path.basename(original_path))

    return unique_keep_order(candidates)


def class_folder_candidates_from_row(row, normalized_label):
    candidates = []

    for column in row.index:
        lower = str(column).lower()
        if "class" in lower or "category" in lower:
            value = str(row[column]).strip()
            if value and value.lower() != "nan":
                candidates.append(value)
                candidates.append(value.replace("-", "_").replace(" ", "_"))
                candidates.append(value.replace("_", "-").replace(" ", "-"))
                candidates.append(value.replace("_", " ").replace("-", " "))

    if int(normalized_label) == 1:
        candidates.extend(["Seizure", "seizure", "SEIZURE"])
    else:
        candidates.extend(
            [
                "Non_Seizure",
                "Non-Seizure",
                "Non Seizure",
                "Non-seizure",
                "non_seizure",
                "non-seizure",
                "non seizure",
            ]
        )

    return unique_keep_order(candidates)


FILENAME_SEARCH_INDEX_CACHE = {}
GLOBAL_IMAGE_FILENAME_INDEX = None
GLOBAL_IMAGE_PATH_LIST = None
IMAGE_EXTENSIONS = {".png", ".jpg", ".jpeg", ".webp", ".bmp", ".tif", ".tiff"}


def build_filename_index(root):
    root = os.path.abspath(os.path.normpath(str(root)))

    if root in FILENAME_SEARCH_INDEX_CACHE:
        return FILENAME_SEARCH_INDEX_CACHE[root]

    filename_index = {}

    if os.path.isdir(root):
        for dirpath, _, filenames in os.walk(root):
            for filename in filenames:
                filename_index.setdefault(filename, []).append(os.path.join(dirpath, filename))

    FILENAME_SEARCH_INDEX_CACHE[root] = filename_index
    return filename_index


def recursive_find_filename(filename, roots):
    filename = os.path.basename(str(filename).strip())
    if not filename:
        return None

    for root in unique_keep_order(roots):
        if not root or not os.path.isdir(root):
            continue

        filename_index = build_filename_index(root)
        matches = filename_index.get(filename, [])

        if matches:
            return sorted(matches, key=lambda path: len(str(path)))[0]

    return None


def build_global_image_filename_index():
    global GLOBAL_IMAGE_FILENAME_INDEX
    global GLOBAL_IMAGE_PATH_LIST

    if GLOBAL_IMAGE_FILENAME_INDEX is not None:
        return GLOBAL_IMAGE_FILENAME_INDEX

    representation = globals().get("REPRESENTATION_NAME", "A5D5D4D3D2").lower()
    search_roots = unique_keep_order(
        list(globals().get("DRIVE_ROOT_CANDIDATES", []))
        + list(globals().get("EXTRA_IMAGE_SEARCH_ROOTS", []))
        + [globals().get("DRIVE_MYDRIVE", "/content/drive/MyDrive")]
    )

    print("\nBuilding one-time Google Drive image filename index...")
    print("Representation filter:", representation)

    index = {}
    scanned_files = 0
    indexed_files = 0

    for root in search_roots:
        if not os.path.isdir(root):
            continue

        for dirpath, _, filenames in os.walk(root):
            dir_text = dirpath.replace("\\", "/").lower()

            # Keep this focused so Drive indexing does not become too expensive.
            if representation not in dir_text:
                continue

            for filename in filenames:
                scanned_files += 1
                extension = os.path.splitext(filename)[1].lower()
                if extension not in IMAGE_EXTENSIONS:
                    continue

                full_path = os.path.join(dirpath, filename)
                index.setdefault(filename, []).append(full_path)
                index.setdefault(filename.lower(), []).append(full_path)
                indexed_files += 1

    all_paths = []
    for paths in index.values():
        all_paths.extend(paths)

    GLOBAL_IMAGE_FILENAME_INDEX = index
    GLOBAL_IMAGE_PATH_LIST = unique_keep_order(all_paths)
    print(f"Indexed {indexed_files} A5D5D4D3D2 image files.")
    return GLOBAL_IMAGE_FILENAME_INDEX


def score_global_image_candidate(candidate_path, dataset_name, normalized_label):
    score = 0
    text = str(candidate_path).replace("\\", "/").lower()
    representation = globals().get("REPRESENTATION_NAME", "A5D5D4D3D2").lower()

    if representation in text:
        score += 100

    patient_id = patient_id_from_dataset_name(dataset_name)
    if patient_id is not None and patient_path_matches(text, patient_id):
        score += 200

    if int(normalized_label) == 1:
        if "seizure" in text and "non" not in text:
            score += 20
    else:
        if "non" in text and "seizure" in text:
            score += 20

    if "blind" in text:
        score += 10
    if "test" in text:
        score += 5
    if "training" in text or "train" in text:
        score -= 3

    return score


def find_image_in_global_drive_index(filename, dataset_name, normalized_label):
    filename = os.path.basename(str(filename).strip())
    if not filename:
        return None

    index = build_global_image_filename_index()
    matches = index.get(filename, []) + index.get(filename.lower(), [])
    matches = unique_keep_order(matches)

    if not matches:
        return None

    scored = sorted(
        [
            (
                score_global_image_candidate(match, dataset_name, normalized_label),
                -len(str(match)),
                match,
            )
            for match in matches
        ],
        reverse=True,
    )

    best_score, _, best_match = scored[0]
    if best_score <= 0:
        return None

    return best_match


def serial_tokens_from_row(row):
    tokens = []

    for column in row.index:
        lower = str(column).lower()
        if "serial" not in lower:
            continue

        value = row[column]
        if pd.isna(value):
            continue

        raw_text = str(value).strip()
        if not raw_text or raw_text.lower() == "nan":
            continue

        tokens.append(raw_text)

        numeric_matches = re.findall(r"\d+", raw_text)
        for numeric_text in numeric_matches:
            numeric_int = int(numeric_text)
            tokens.append(str(numeric_int))
            for width in [4, 5, 6, 7, 8]:
                tokens.append(str(numeric_int).zfill(width))

    cleaned_tokens = []
    for token in unique_keep_order(tokens):
        token = str(token).strip()
        if not token:
            continue

        # Avoid tiny serial fragments like "1" or "24" matching many unrelated files.
        if len(token) < 3:
            continue

        cleaned_tokens.append(token.lower())

    return unique_keep_order(cleaned_tokens)


def find_image_by_serial_in_global_drive_index(row, dataset_name, normalized_label):
    build_global_image_filename_index()

    serial_tokens = serial_tokens_from_row(row)
    if not serial_tokens:
        return None

    if not GLOBAL_IMAGE_PATH_LIST:
        return None

    matches = []
    for path in GLOBAL_IMAGE_PATH_LIST:
        basename = os.path.basename(path).lower()
        path_text = str(path).replace("\\", "/").lower()

        if not any(token in basename or token in path_text for token in serial_tokens):
            continue

        score = score_global_image_candidate(path, dataset_name, normalized_label)

        # Prefer serial matches in the filename itself over folder-only matches.
        if any(token in basename for token in serial_tokens):
            score += 50

        matches.append((score, -len(str(path)), path))

    if not matches:
        return None

    scored = sorted(matches, reverse=True)
    best_score, _, best_match = scored[0]

    if best_score <= 0:
        return None

    return best_match


def nearby_image_search_roots(csv_path, original_path):
    csv_dir = os.path.dirname(os.path.abspath(csv_path))
    csv_parent = os.path.dirname(csv_dir)
    csv_grandparent = os.path.dirname(csv_parent)
    csv_great_grandparent = os.path.dirname(csv_grandparent)

    roots = [
        csv_dir,
        csv_parent,
        csv_grandparent,
        csv_great_grandparent,
    ]

    for candidate in google_drive_path_variants(original_path):
        candidate_dir = os.path.dirname(candidate)
        roots.extend(
            [
                candidate_dir,
                os.path.dirname(candidate_dir),
                os.path.dirname(os.path.dirname(candidate_dir)),
            ]
        )

    combined_text = f"{csv_path} {original_path}".replace("\\", "/")

    patient_folder_candidates = []
    if "Patient 24" in combined_text or "Patiient 24" in combined_text:
        patient_folder_candidates.extend(["Patient 24", "Patiient 24"])
    if "Patient 18" in combined_text:
        patient_folder_candidates.append("Patient 18")
    if "Patient 11" in combined_text:
        patient_folder_candidates.append("Patient 11")
    if "Patient 08" in combined_text or "Patient 8" in combined_text:
        patient_folder_candidates.extend(["Patient 08", "Patient 8"])

    representation = globals().get("REPRESENTATION_NAME", "A5D5D4D3D2")
    for drive_root in globals().get("DRIVE_ROOT_CANDIDATES", []):
        for patient_folder in patient_folder_candidates:
            roots.append(os.path.join(drive_root, patient_folder, representation))

    return unique_keep_order(roots)


def resolve_image_path_from_metadata(row, csv_path, image_column, normalized_label, dataset_name):
    original_path = clean_path(row[image_column])
    if original_path and os.path.isfile(original_path):
        return original_path, False

    for candidate in google_drive_path_variants(original_path):
        if os.path.isfile(candidate):
            return candidate, True

    csv_dir = os.path.dirname(os.path.abspath(csv_path))
    csv_parent = os.path.dirname(csv_dir)
    csv_grandparent = os.path.dirname(csv_parent)
    candidate_roots = unique_keep_order(
        [
            csv_dir,
            csv_parent,
            csv_grandparent,
            os.path.join(csv_dir, "Blinded"),
            os.path.join(csv_dir, "bLINDED"),
            os.path.join(csv_dir, "Blinnded"),
            os.path.join(csv_dir, "Blinded Topomaps"),
            os.path.join(csv_dir, "Blinded folder"),
            os.path.join(csv_parent, "Blinded"),
            os.path.join(csv_parent, "bLINDED"),
            os.path.join(csv_parent, "Blinnded"),
            os.path.join(csv_parent, "Blinded Topomaps"),
            os.path.join(csv_parent, "Blinded folder"),
            os.path.join(csv_grandparent, "Testing", "Blinded"),
            os.path.join(csv_grandparent, "Testing", "bLINDED"),
            os.path.join(csv_grandparent, "Testing", "Blinnded"),
            os.path.join(csv_grandparent, "Testing", "Blinded Topomaps"),
            os.path.join(csv_grandparent, "Testing", "Blinded folder"),
            os.path.join(csv_dir, "Testing"),
            os.path.join(csv_dir, "Training"),
        ]
    )

    filenames = filename_candidates_from_row(row, image_column)
    class_folders = class_folder_candidates_from_row(row, normalized_label)

    candidate_paths = []

    for root in candidate_roots:
        for filename in filenames:
            candidate_paths.append(os.path.join(root, filename))
            for class_folder in class_folders:
                candidate_paths.append(os.path.join(root, class_folder, filename))

    expanded_candidate_paths = []
    for candidate_path in candidate_paths:
        expanded_candidate_paths.extend(path_spelling_variants(candidate_path))

    for candidate_path in unique_keep_order(expanded_candidate_paths):
        candidate_path = os.path.normpath(candidate_path)
        if os.path.isfile(candidate_path):
            return candidate_path, True

    search_roots = nearby_image_search_roots(csv_path, original_path)
    for filename in filenames:
        found_path = recursive_find_filename(filename, search_roots)
        if found_path is not None:
            return found_path, True

    for filename in filenames:
        found_path = find_image_in_global_drive_index(
            filename=filename,
            dataset_name=dataset_name,
            normalized_label=normalized_label,
        )
        if found_path is not None:
            return found_path, True

    found_path = find_image_by_serial_in_global_drive_index(
        row=row,
        dataset_name=dataset_name,
        normalized_label=normalized_label,
    )
    if found_path is not None:
        return found_path, True

    return original_path, False


def detect_image_path_column(df, dataset_type):
    if dataset_type == "test":
        candidates = [
            "blinded_image_path",
            "blinded_topomap_path",
            "blinded_path",
            "blinded_image_filename",
            "blinded_topomap_filename",
            "fine_tuning_image_path",
            "image_path",
            "image_filename",
            "image_file",
            "image_name",
            "topomap_filename",
            "topomap_file",
            "topomap_name",
            "selected_image_path",
            "original_image_path",
            "file_path",
            "filepath",
            "filename",
            "file_name",
            "path",
        ]
    else:
        candidates = [
            "fine_tuning_image_path",
            "image_path",
            "image_filename",
            "image_file",
            "image_name",
            "topomap_filename",
            "topomap_file",
            "topomap_name",
            "selected_image_path",
            "blinded_image_path",
            "blinded_topomap_path",
            "blinded_path",
            "blinded_image_filename",
            "blinded_topomap_filename",
            "original_image_path",
            "file_path",
            "filepath",
            "filename",
            "file_name",
            "path",
        ]

    for candidate in candidates:
        if candidate in df.columns:
            return candidate

    for column in df.columns:
        lower = str(column).lower()
        if "path" in lower and ("image" in lower or "topomap" in lower or "blinded" in lower):
            return column
        if "filename" in lower and ("image" in lower or "topomap" in lower or "blind" in lower):
            return column

    raise ValueError(f"Could not detect image path column. Columns: {list(df.columns)}")


def detect_label_column(df):
    candidates = [
        "standard_label",
        "true_label",
        "label",
        "Label",
        "target",
        "true_class",
        "class_label",
        "class_name",
        "fine_tuning_class",
        "class_folder",
        "class",
        "category",
    ]

    for candidate in candidates:
        if candidate in df.columns:
            return candidate

    for column in df.columns:
        lower = str(column).lower()
        if "label" in lower or lower == "class":
            return column

    return None


def normalize_ground_truth_label(value):
    if pd.isna(value):
        return None

    if isinstance(value, (int, np.integer)):
        if int(value) == 1:
            return 1
        if int(value) == 0:
            return 0

    if isinstance(value, (float, np.floating)):
        if float(value) == 1.0:
            return 1
        if float(value) == 0.0:
            return 0

    text = str(value).strip().lower()
    text = text.replace("_", " ").replace("–", "-")
    text = re.sub(r"\s+", " ", text)

    if text in {"0", "0.0", "non seizure", "non-seizure", "nonseizure", "normal", "interictal", "ns"}:
        return 0
    if "non" in text and "seizure" in text:
        return 0
    if text in {"1", "1.0", "seizure", "ictal", "sz"}:
        return 1
    if "seizure" in text:
        return 1

    return None


def label_inference_columns(df):
    priority_columns = []

    for column in df.columns:
        lower = str(column).lower()

        if any(token in lower for token in ["label", "target", "category"]):
            priority_columns.append(column)
            continue

        if "class" in lower and "position" not in lower:
            priority_columns.append(column)
            continue

    for column in df.columns:
        lower = str(column).lower()

        if lower in {"filename", "file_name", "image_filename", "blinded_filename"}:
            priority_columns.append(column)
            continue

        if (
            ("filename" in lower or "path" in lower)
            and
            ("image" in lower or "topomap" in lower or "blind" in lower or "original" in lower)
        ):
            priority_columns.append(column)

    return unique_keep_order(priority_columns)


def infer_ground_truth_label_from_row(row, columns):
    for column in columns:
        label = normalize_ground_truth_label(row[column])
        if label is not None:
            return label

    return None


def load_and_standardize_metadata(csv_path, dataset_name, dataset_type):
    print("\n" + "=" * 100)
    print(f"LOADING {dataset_name.upper()}")
    print("=" * 100)

    csv_path = resolve_csv_path(csv_path, dataset_name)

    df = pd.read_csv(csv_path)
    print(f"\nRows: {len(df)}")
    print("\nColumns:")
    for column in df.columns:
        print("  ", column)

    image_column = detect_image_path_column(df, dataset_type)
    label_column = detect_label_column(df)
    print(f"\nImage path column: {image_column}")

    df["_image_path_original"] = df[image_column].apply(clean_path)

    if label_column is None:
        inference_columns = label_inference_columns(df)

        print("Label column     : inferred from metadata")
        print("Label inference columns:")
        for column in inference_columns:
            print("  ", column)

        if not inference_columns:
            raise ValueError(
                "Could not detect or infer a label column. "
                f"Columns: {list(df.columns)}"
            )

        df["_label"] = df.apply(
            lambda row: infer_ground_truth_label_from_row(row, inference_columns),
            axis=1
        )
    else:
        print(f"Label column     : {label_column}")
        df["_label"] = df[label_column].apply(normalize_ground_truth_label)

    invalid_labels = df[df["_label"].isna()]
    if len(invalid_labels) > 0:
        if label_column is None:
            preview_columns = label_inference_columns(df)
            print(invalid_labels[preview_columns].head(20))
        else:
            print(invalid_labels[[label_column]].drop_duplicates())
        raise ValueError("Some labels could not be interpreted.")

    df["_label"] = df["_label"].astype(int)

    resolved_paths = []
    repaired_count = 0

    for _, row in df.iterrows():
        resolved_path, repaired = resolve_image_path_from_metadata(
            row=row,
            csv_path=csv_path,
            image_column=image_column,
            normalized_label=int(row["_label"]),
            dataset_name=dataset_name,
        )
        resolved_paths.append(resolved_path)
        if repaired:
            repaired_count += 1

    df["_image_path"] = resolved_paths

    if repaired_count > 0:
        print(
            f"\nRepaired {repaired_count} image paths from the CSV folder "
            "using filename/class metadata."
        )

    missing_images = []
    for image_path in df["_image_path"]:
        if not os.path.isfile(image_path):
            missing_images.append(image_path)

    if missing_images:
        print(f"\nMissing images: {len(missing_images)}")
        print("\nThe CSV was found, but these image paths still do not exist.")
        print("Most likely the image_path column points to an old folder.")
        print("CSV folder used for automatic repair:")
        print(os.path.dirname(os.path.abspath(csv_path)))
        print("\nFirst missing paths:")
        for image_path in missing_images[:20]:
            print(image_path)
        raise FileNotFoundError("One or more images are missing.")

    duplicate_count = int(df["_image_path"].duplicated().sum())
    if duplicate_count > 0:
        raise ValueError(f"{duplicate_count} duplicate image paths detected in {dataset_name}.")

    seizure_count = int((df["_label"] == 1).sum())
    non_seizure_count = int((df["_label"] == 0).sum())

    print("\nClass counts:")
    print(f"Seizure     : {seizure_count}")
    print(f"Non-seizure : {non_seizure_count}")
    print(f"Total       : {len(df)}")
    print(f"\nAll {len(df)} image paths exist.")

    return df, image_column, label_column


full_training_df, train_image_column, train_label_column = load_and_standardize_metadata(
    TRAINING_METADATA_CSV,
    "pooled A5D5D4D3D2 training pool",
    "train",
)

if len(full_training_df) != EXPECTED_FULL_TRAIN_TOTAL:
    raise AssertionError(
        f"The pooled training CSV should contain {EXPECTED_FULL_TRAIN_TOTAL} rows, "
        f"but found {len(full_training_df)}."
    )

testing_dfs = {}
testing_column_info = {}

for patient_id, csv_path in TEST_METADATA_CSVS.items():
    test_df, image_column, label_column = load_and_standardize_metadata(
        csv_path,
        f"Patient {patient_id} A5D5D4D3D2 blinded test",
        "test",
    )
    testing_dfs[patient_id] = test_df
