# ==================================================================================================
# 10. PROMPT, COLLATOR, LOADERS
# ==================================================================================================

def label_to_target_text(label):
    if int(label) == 1:
        return "Seizure"
    return "Non-Seizure"


def build_prompt_messages(image):
    return [
        {
            "role": "system",
            "content": [{"type": "text", "text": SYSTEM_PROMPT}],
        },
        {
            "role": "user",
            "content": [
                {"type": "text", "text": USER_PROMPT},
                {"type": "image", "image": image},
            ],
        },
    ]


def build_training_messages(image, target_text):
    messages = build_prompt_messages(image)
    messages.append(
        {
            "role": "assistant",
            "content": [{"type": "text", "text": target_text}],
        }
    )
    return messages


def tokenize_answer_text(label_text):
    # Leading space makes the target behave like the first generated word after the assistant header.
    # This avoids a common chat-template edge case where the supervised target can tokenize oddly.
    text = " " + str(label_text).strip()
    tokenized = processor.tokenizer(
        text,
        add_special_tokens=False,
        return_tensors="pt",
    )
    answer_ids = tokenized["input_ids"]
    if answer_ids.ndim != 2 or answer_ids.shape[0] != 1 or answer_ids.shape[1] == 0:
        raise RuntimeError(f"Could not tokenize answer text: {label_text!r}")
    return answer_ids


def append_target_tokens_to_prompt(prompt_inputs, answer_ids):
    prompt_ids = prompt_inputs["input_ids"]
    prompt_length = int(prompt_ids.shape[1])
    answer_length = int(answer_ids.shape[1])
    answer_ids = answer_ids.to(dtype=prompt_ids.dtype)

    full_inputs = {}
    for key, value in prompt_inputs.items():
        if not torch.is_tensor(value):
            full_inputs[key] = value
            continue

        if key == "input_ids":
            full_inputs[key] = torch.cat([value, answer_ids], dim=1)
            continue

        if key == "attention_mask":
            answer_mask = torch.ones(
                (value.shape[0], answer_length),
                dtype=value.dtype,
                device=value.device,
            )
            full_inputs[key] = torch.cat([value, answer_mask], dim=1)
            continue

        if key in {"token_type_ids", "position_ids"} and value.ndim == 2 and value.shape[1] == prompt_length:
            answer_pad = torch.zeros(
                (value.shape[0], answer_length),
                dtype=value.dtype,
                device=value.device,
            )
            full_inputs[key] = torch.cat([value, answer_pad], dim=1)
            continue

        full_inputs[key] = value

    labels = torch.full_like(full_inputs["input_ids"], -100)
    labels[:, prompt_length:] = answer_ids

    supervised_token_count = int((labels != -100).sum())
    if supervised_token_count != answer_length:
        raise RuntimeError(
            f"Expected {answer_length} supervised answer tokens, found {supervised_token_count}."
        )

    full_inputs["labels"] = labels
    return full_inputs, prompt_length, answer_length


class MedGemmaTrainingCollator:
    def __init__(self, processor):
        self.processor = processor

    def __call__(self, examples):
        if len(examples) != 1:
            raise ValueError("This pipeline expects physical batch size = 1.")

        example = examples[0]
        image_path = example["image_path"]
        target_text = label_to_target_text(example["label"])

        with Image.open(image_path) as opened_image:
            image = opened_image.convert("RGB")

            prompt_messages = build_prompt_messages(image)
            prompt_inputs = self.processor.apply_chat_template(
                prompt_messages,
                add_generation_prompt=True,
                tokenize=True,
                return_dict=True,
                return_tensors="pt",
            )

        answer_ids = tokenize_answer_text(target_text)
        full_inputs, _, _ = append_target_tokens_to_prompt(prompt_inputs, answer_ids)
        return full_inputs


train_dataset = EEGTopomapDataset(actual_train_df)
validation_dataset = EEGTopomapDataset(validation_df)
training_collator = MedGemmaTrainingCollator(processor)

train_generator = torch.Generator()
train_generator.manual_seed(RANDOM_SEED)

train_loader = DataLoader(
    train_dataset,
    batch_size=TRAIN_BATCH_SIZE,
    shuffle=True,
    generator=train_generator,
    num_workers=NUM_WORKERS,
    collate_fn=training_collator,
)

validation_loss_loader = DataLoader(
    validation_dataset,
    batch_size=VALIDATION_BATCH_SIZE,
    shuffle=False,
    num_workers=NUM_WORKERS,
    collate_fn=training_collator,
)


def move_batch_to_device(batch):
    moved = {}
    for key, value in batch.items():
        if not torch.is_tensor(value):
            moved[key] = value
        elif value.dtype.is_floating_point:
            moved[key] = value.to(device=DEVICE, dtype=MODEL_DTYPE)
        else:
            moved[key] = value.to(DEVICE)
    return moved


def autocast_context():
    return torch.autocast(device_type="cuda", dtype=MODEL_DTYPE)


